import { Component, inject } from '@angular/core';
import { OverlayModule } from '@angular/cdk/overlay';
import {
  AuthService,
  DiscussionComponent,
  DiscussionDto,
  DiscussionIconComponent,
  DiscussionListComponent,
  DiscussionPanelComponent,
  DiscussionService,
  MessageComponent,
  TooltipDirective,
} from 'vitamui-library';
import { AsyncPipe } from '@angular/common';
import { Observable } from 'rxjs';
import { DiscussionServiceMock } from 'vitamui-library/testing';

@Component({
  imports: [
    AsyncPipe,
    TooltipDirective,
    DiscussionComponent,
    DiscussionIconComponent,
    DiscussionListComponent,
    DiscussionPanelComponent,
    MessageComponent,
    OverlayModule,
    MessageComponent,
  ],
  templateUrl: './design-system-discussion.component.html',
  styles: `
    .bg-grey {
      background: var(--vitamui-grey-400);
    }
  `,
  providers: [
    {
      provide: DiscussionService,
      useClass: DiscussionServiceMock,
    },
    {
      provide: AuthService,
      useValue: { user: { id: 'me' } },
    },
  ],
})
export class DesignSystemDiscussionComponent {
  discussions$: Observable<DiscussionDto[]> = inject(DiscussionService).findDiscussions({ type: 'mockType', id: 'mockId' });
}
