import { Component, effect, inject, signal, untracked } from '@angular/core';
import { Route, Router, RouterLink, RouterLinkActive, RouterOutlet, Routes } from '@angular/router';
import {
  AppConfiguration,
  ApplicationApiService,
  AuthService,
  ConfigService,
  SelectComponent,
  SelectLanguageComponent,
  ThemeService,
  VitamuiSelectOptions,
} from 'vitamui-library';
import { form, FormField } from '@angular/forms/signals';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';
import { RouteData } from './app.routes';
import { MatSidenav, MatSidenavContainer, MatSidenavContent } from '@angular/material/sidenav';
import { MatList } from '@angular/material/list';
import { MatAccordion, MatExpansionPanel, MatExpansionPanelHeader } from '@angular/material/expansion';
import { CommonModule, NgTemplateOutlet } from '@angular/common';
import { MatSelectModule } from '@angular/material/select';
import { MatMenuModule } from '@angular/material/menu';
import { MatButtonModule } from '@angular/material/button';

@Component({
  selector: 'design-system-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss'],
  imports: [
    MatSidenavContainer,
    MatSidenav,
    FormField,
    SelectComponent,
    MatList,
    MatAccordion,
    MatExpansionPanel,
    MatExpansionPanelHeader,
    RouterLinkActive,
    RouterLink,
    NgTemplateOutlet,
    MatSidenavContent,
    RouterOutlet,
    TranslatePipe,
    CommonModule,
    MatButtonModule,
    MatMenuModule,
    MatSelectModule,
    SelectLanguageComponent,
  ],
})
export class AppComponent {
  private readonly router = inject(Router);

  title = 'Design system App';

  routes: Routes;
  readonly searchOptions = signal<VitamuiSelectOptions>(undefined);
  readonly form = form(signal<{ search: string }>({ search: '' }));
  url: string;

  constructor() {
    const authService = inject(AuthService);
    const configService = inject(ConfigService);
    const themeService = inject(ThemeService);
    const applicationApiService = inject(ApplicationApiService);

    authService.userInfo = { id: '42', language: 'FRENCH' };

    applicationApiService.getLocalAsset(configService.config.USER_LOGO).subscribe((userLogo) => {
      themeService.init(
        {
          USER_LOGO: userLogo,
          THEME_COLORS: configService.config.THEME_COLORS,
        } as AppConfiguration,
        {},
      );
    });

    const router = this.router;
    const translateService = inject(TranslateService);

    this.routes = router.config;

    function extractSearchData(context: string, route: Route, acc: VitamuiSelectOptions) {
      const pathWithContext = [context, route.path].join('/');
      if (route.children) {
        route.children.forEach((child) => extractSearchData(pathWithContext, child, acc));
      } else if (route.path && route.redirectTo === undefined) {
        const data: RouteData = route.data;
        const altSearch = data?.altSearch
          ? ([...(data.altSearch._ || []), ...(data.altSearch[translateService.getCurrentLang()] || [])] as string[])
          : [];
        const routeTitle = translateService.instant(`ROUTE${pathWithContext.replace(/\//g, '.')}.TITLE`);
        const options = [routeTitle, ...altSearch].map((s) => ({ key: pathWithContext, label: s }));
        acc.options.push(...options);
      }
      return acc;
    }

    // Make sure the translations are loaded, and reload on translation change
    translateService.onLangChange.subscribe(() => {
      this.searchOptions.set(
        this.routes.reduce(
          (acc, route) => {
            extractSearchData('', route, acc);
            return acc;
          },
          { options: [], customSorting: (a, b) => a.label.localeCompare(b.label) } as VitamuiSelectOptions,
        ),
      );
    });

    effect(() => {
      const value = this.form.search().value();
      if (value) {
        untracked(() => {
          router.navigateByUrl(value);
          setTimeout(() => this.form().reset({ search: '' }));
        });
      }
    });
  }

  isActive(url: string): boolean {
    return this.router.isActive(url, {
      paths: 'subset',
      queryParams: 'subset',
      fragment: 'ignored',
      matrixParams: 'ignored',
    });
  }
}
