import {
  AfterViewInit,
  Component,
  ElementRef,
  OnInit,
  resource,
  inject,
  signal,
  afterNextRender,
  Injector,
  viewChildren,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import {
  CountryOption,
  CountryService,
  FormFieldValueWrapperComponent,
  Option,
  SelectComponent,
  requiredValue,
  SlideToggleComponent,
  VitamuiSelectOptions,
} from 'vitamui-library';
import { disabled, FieldTree, form, FormField, patternError, validate } from '@angular/forms/signals';
import { AsyncPipe, JsonPipe } from '@angular/common';
import { extend } from 'underscore';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

type SelectValue = string | string[] | null;

const GB_PATTERN = /^.*GB.*$/;

@Component({
  imports: [AsyncPipe, FormFieldValueWrapperComponent, FormField, JsonPipe, SelectComponent, SlideToggleComponent, TranslatePipe],
  templateUrl: './design-system-select.component.html',
  styleUrl: './design-system-select.component.scss',
})
export class DesignSystemSelectComponent implements OnInit, AfterViewInit {
  private readonly countryService = inject(CountryService);

  private readonly injector = inject(Injector);

  readonly configs = signal<
    {
      name: string;
      multiple?: boolean;
      entries: { type: string; states: { id: string; field: FieldTree<SelectValue> }[] }[];
    }[]
  >(undefined);

  readonly displayOptions = form(signal({ enableSearch: false, enableSelectAll: false, enableDisplaySelected: false }));

  multiSelectOptions$: Observable<VitamuiSelectOptions>;

  readonly wrapperField = form(signal<string | null>('FR'));

  loadingOptions = resource<VitamuiSelectOptions | any[], unknown>({
    loader: () =>
      new Promise((resolve) => {
        setTimeout(() => {
          resolve(['AAA', 'BBB']);
          setTimeout(() => this.loadingOptions.reload(), 5_000);
        }, 5_000);
      }),
  });

  readonly components = viewChildren(SelectComponent, { read: ElementRef });

  ngOnInit() {
    this.initMultiselectOptions();
  }

  ngAfterViewInit() {
    this.multiSelectOptions$.subscribe((options) => {
      const selectedOptionValue = options.options[0].key;
      this.configs.set([
        {
          name: 'Simple select',
          multiple: false,
          entries: this.getEntries(selectedOptionValue),
        },
        {
          name: 'Multiple select',
          multiple: true,
          entries: this.getEntries([selectedOptionValue]),
        },
      ]);
      // Focus the "Active" selects once they are rendered
      afterNextRender(
        () => {
          this.components().forEach((component) => {
            const nativeElement = component.nativeElement as HTMLElement;
            const isActive = nativeElement.getAttribute('data-active') === 'true';
            if (isActive) nativeElement.querySelector('mat-select').dispatchEvent(new Event('focus'));
          });
        },
        { injector: this.injector },
      );
    });
  }

  private getEntries(selectedOptionValue: any) {
    return [
      {
        type: 'empty',
        states: [
          { id: 'Default', field: this.createField() },
          { id: 'Active', field: this.createField() },
          { id: 'Disabled', field: this.createField({ disabled: true }) },
          { id: 'Error', field: this.createField({ error: true }) },
        ],
      },
      {
        type: 'full',
        states: [
          { id: 'Default', field: this.createField({ value: selectedOptionValue }) },
          { id: 'Active', field: this.createField({ value: selectedOptionValue }) },
          { id: 'Disabled', field: this.createField({ disabled: true, value: selectedOptionValue }) },
          { id: 'Error', field: this.createField({ error: true, value: selectedOptionValue }) },
        ],
      },
    ];
  }

  private createField(config?: { disabled?: boolean; error?: boolean; value?: SelectValue }): FieldTree<SelectValue> {
    const field = form(
      signal<SelectValue>(config?.value ?? null),
      (path) => {
        if (config?.error || config?.disabled) {
          requiredValue(path);
          // Same as Validators.pattern('.*GB.*'), which also applies to the comma-separated values of a multiple select
          validate(path, ({ value }) => (value()?.length && !GB_PATTERN.test(String(value())) ? patternError(GB_PATTERN) : undefined));
        }
        if (config?.disabled) {
          disabled(path);
        }
      },
      { injector: this.injector },
    );
    if (config?.error) field().markAsTouched();
    return field;
  }

  private initMultiselectOptions(): void {
    this.multiSelectOptions$ = this.countryService.getAvailableCountries().pipe(
      map((values: CountryOption[]) => {
        const countries = values.map((value) =>
          extend({
            key: value.code,
            label: value.name,
            disabled: value.code === 'DK',
          }),
        );
        return { options: countries, customSorting: this.sortAlphabetically };
      }),
    );
  }

  private readonly sortAlphabetically = (a: Option, b: Option): number => {
    return a.label.toLocaleLowerCase() > b.label.toLocaleLowerCase() ? 1 : -1;
  };
  protected readonly Object = Object;
}
