import {
  enableProdMode,
  importProvidersFrom,
  inject,
  LOCALE_ID,
  provideAppInitializer,
  provideZonelessChangeDetection,
} from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';

import { registerLocaleData } from '@angular/common';
import { default as localeFr } from '@angular/common/locales/fr';
import { environment } from './environments/environment';
import {
  BaseUserInfoApiService,
  ConfigService,
  ENVIRONMENT,
  loadConfigFactory,
  LoggerModule,
  provideI18n,
  provideVitamuiFeature,
  VitamUILibraryModule,
  WINDOW_LOCATION,
} from 'vitamui-library';
import { provideNativeDateAdapter } from '@angular/material/core';
import { of } from 'rxjs';
import { AppComponent } from './app/app.component';
import { ServiceWorkerModule } from '@angular/service-worker';
import { PreloadAllModules, provideRouter, withHashLocation, withPreloading } from '@angular/router';
import { routes } from './app/app.routes';

registerLocaleData(localeFr, 'fr');

if (environment.production) {
  enableProdMode();
}

bootstrapApplication(AppComponent, {
  providers: [
    provideZonelessChangeDetection(),
    provideRouter(routes, withPreloading(PreloadAllModules), withHashLocation()),
    importProvidersFrom(
      LoggerModule.forRoot(),
      ServiceWorkerModule.register('ngsw-worker.js', {
        enabled: environment.production,
        // Register the ServiceWorker as soon as the application is stable
        // or after 30 seconds (whichever comes first).
        registrationStrategy: 'registerWhenStable:30000',
      }),
      VitamUILibraryModule, // For Material tokens
    ),
    provideAppInitializer(async () => {
      const configService = inject(ConfigService);
      const environment = inject(ENVIRONMENT);
      await loadConfigFactory(configService, environment)();
    }),
    provideI18n(),
    provideNativeDateAdapter(),
    { provide: LOCALE_ID, useValue: 'fr' },
    { provide: ENVIRONMENT, useValue: environment },
    provideVitamuiFeature({ baseUrl: '/FAKE' }),
    {
      provide: WINDOW_LOCATION,
      useValue: window.location,
    },
    { provide: BaseUserInfoApiService, useValue: { patchMyUserInfo: () => of(undefined) } }, // Make changing language work
  ],
}).catch((err) => console.log(err));
